-- ---------------------------------------------------------------------
-- STATUS SZINKRON (kötelező)
-- unavailable lista fixen marad unavailable,
-- minden más: ha van aktív assignment -> assigned, különben available.
-- ---------------------------------------------------------------------

UPDATE devices d
LEFT JOIN assignments a
  ON a.device_id = d.id AND a.returned_at IS NULL
SET d.status = CASE
  WHEN d.id IN (6,18,27,33,46,58,69,74,85,97) THEN 'unavailable'
  WHEN a.id IS NOT NULL THEN 'assigned'
  ELSE 'available'
END;


